using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Assets.Script.DynamicCards;
public static class MotionWork {public static void Run(){var root=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/DynamicCards/Content/Old/Legacy2017/14210601/Card.prefab");var text=new System.Text.StringBuilder();foreach(var tr in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name.Contains("Wings"))){text.AppendLine(AnimationUtility.CalculateTransformPath(tr,root.transform));foreach(var r in tr.GetComponents<Renderer>())text.AppendLine(r.GetType().Name+" "+string.Join(",",r.sharedMaterials.Select(m=>m==null?"NULL":m.name)));}File.WriteAllText(@"C:/UnityProjects/LegacyGwent/work/DynamicCards/MotionIntegrity/main-surface-probe.txt",text.ToString());}}
